 function risks(d){
  var r=[],today=day(now());
  function add(level,icon,title,copy,weight){r.push({level:level,icon:icon,title:title,copy:copy,weight:weight,doc:d})}
  if(!d.company)add('medium','🏢','Company is not linked','The document cannot appear in a company record until a company is selected.',16);
  if(!d.url&&!d.attachmentId)add('high','📎','Document content is not reachable','No browser attachment or external URL is recorded.',30);
  if((d.approvalStatus==='Pending Internal'||d.approvalStatus==='Pending Customer')&&!d.approvalDueDate)add('medium','✓','Approval has no due date','Pending approval should have an accountable review date.',20);
  if(d.approvalDueDate&&(d.approvalStatus==='Pending Internal'||d.approvalStatus==='Pending Customer')&&day(d.approvalDueDate)<today)add('high','⏰','Approval is overdue','Approval was due '+fmt(d.approvalDueDate)+'.',38);
  if(d.expirationDate&&d.status==='Active'){var left=days(today,d.expirationDate);if(left<0)add('high','⌛','Active document is expired','Expiration was '+fmt(d.expirationDate)+'.',40);else if(left<=30)add('medium','⌛','Document expires soon',left+' days remain until '+fmt(d.expirationDate)+'.',24)}
  if(['Contract','Pricing Agreement','Tax Form','Credit Application'].indexOf(d.type)>=0&&d.status==='Active'&&!d.expirationDate)add('medium','📅','Renewal or expiration date is missing','Commercial and compliance documents should be reviewed for a current validity date.',16);
  if((d.type==='Artwork'||d.type==='Proof')&&d.approvalStatus==='Not Required')add('medium','🎨','Approval requirement is not documented','Confirm whether this artwork or proof requires internal or customer approval.',18);
  if(d.sensitivity==='Restricted'&&d.url)add('medium','🔒','Restricted document uses an external URL','Confirm the shared link has appropriate access controls.',20);
  if(d.status==='Superseded'&&!d.supersededBy)add('medium','↻','Superseded version lacks a successor link','Version history cannot identify the active replacement.',12);
  return r
 }
