  if(g.expired.length||g.expiring.length)return{tone:'warn',title:'Renewal and expiration work needs attention',copy:(g.expired.length+g.expiring.length)+' active document'+(g.expired.length+g.expiring.length===1?' is':'s are')+' expired or within 30 days of expiration.'};
  if(g.pending.length)return{tone:'info',title:'Approvals are actively moving',copy:g.pending.length+' document'+(g.pending.length===1?' is':'s are')+' awaiting an internal or customer decision.'};
